"Что произошло потом?": "Que s'est-il passé ensuite ?",
"Что произошло потом? Утром Алия нашла в саду птенца. Она осторожно положила его в коробку и напоила водой. Через два дня птенец окреп и улетел.": "Que s'est-il passé ensuite ? Le matin, Aliya a trouvé un oisillon dans le jardin. Elle l'a délicatement mis dans une boîte et lui a donné de l'eau. Deux jours plus tard, l'oisillon avait pris des forces et s'est envolé.",
"Потом произошло: Бека заблудился в лесу": "Ensuite, voici ce qui s'est passé : Beka s'est perdu dans la forêt",
"Что произошло потом? Бека пошёл за грибами. В лесу он заблудился. Тогда он вспомнил совет отца, пошёл по тропинке и скоро вышел к дому.": "Que s'est-il passé ensuite ? Beka est allé cueillir des champignons. Il s'est perdu dans la forêt. Puis il s'est souvenu du conseil de son père, a suivi un sentier et est bientôt arrivé à la maison.",
"Потом произошло: Дети принесли доски и молотки": "Ensuite, voici ce qui s'est passé : Les enfants ont apporté des planches et des marteaux",
